import json
from collections import Counter


def main():
    counts = Counter()
    with open("app.log") as f:
        for line in f:
            parts = line.split()
            if parts:
                counts[parts[0]] += 1

    report = {level: counts.get(level, 0) for level in ("INFO", "WARN", "ERROR")}
    with open("report.json", "w") as f:
        json.dump(report, f)

    print(report)


if __name__ == "__main__":
    main()

